from pathlib import Path
import json,hashlib,datetime,zipfile
ROOT=Path(__file__).resolve().parents[1];BASE=ROOT/'artifacts/analog_asic'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def rel(p):return p.relative_to(ROOT).as_posix()
def main():
 old=BASE/'assembly/article_module_catalog_v5.json';cat=json.loads(old.read_text());assert all(sha(ROOT/n)==h for n,h in cat['sha256'].items());paths={old,Path(__file__)};reports={}
 specs=[('gf180_guarded_weight_duration_parent_v1','screen_gf180_guarded_weight_duration_parent_nominal.py','gf180_guarded_weight_duration_parent_nominal_src'),('gf180_guarded_weight_duration_parent_v2','screen_gf180_guarded_weight_duration_parent_v2_nominal.py','gf180_guarded_weight_duration_parent_v2_nominal_src'),('gf180_signed_weight_charge_parent_v2','aggregate_gf180_signed_weight_charge_cases.py','gf180_signed_weight_charge_parent_v2_sequential_src')]
 for cell,script,prefix in specs:
  d=BASE/'layout'/cell;rp=BASE/'results'/(prefix+sha(ROOT/'scripts'/script)[:12]+'.json');r=json.loads(rp.read_text());reports[cell]=r;q=json.loads((d/'qualification.json').read_text());fq=json.loads((d/'flat_cap_qualification.json').read_text());assert r['module_simulation_completed'] and q['magic_drc_count']==q['gds_roundtrip_drc_count']==0 and q['lvs_unique'] and q['gds_roundtrip_lvs_unique'] and fq['flat_lvs_unique'] and not fq['negative_aggregate_branches']
  files=[d/(cell+'.gds'),d/(cell+'.lef'),d/(cell+'_flat_cap.spice'),d/'qualification.json',d/'abstract_qualification.json',d/'flat_cap_qualification.json',rp];paths.update(files)
  cat['characterization_assemblies'].append({'cell':cell,'mos_count':q['mos_count'],'native_mim_count':q['native_mim_count'],'ports':q['ports'],'bbox_um':q['bbox_um'],'dense_resident_leaf':False,'module_layout_and_nominal_simulation_artifacts_complete':True,'complete_neuron_functionally_accepted':False,'views':{p.name:rel(p) for p in files},'limitations':r['scope']})
  for p in files:cat['sha256'][rel(p)]=sha(p)
 cat['revision']=6;cat['previous_catalog']=rel(old);cat['next_assembly']='Shared bias/reference and autonomous phase sequencing, adaptation/inhibition/readout interfaces, compact dense tile and full executed graph. Characterize float transfer without per-weight numerical correction.'
 cp=BASE/'assembly/article_module_catalog_v6.json';assert not cp.exists();cp.write_text(json.dumps(cat,indent=2)+'\n');paths.add(cp)
 g1=reports[specs[0][0]];g2=reports[specs[1][0]];signed=reports[specs[2][0]]
 audit={'catalog':rel(cp),'module_artifact_sets':len(cat['modules']),'characterization_assemblies':len(cat['characterization_assemblies']),'guard_v1_cases':g1['cases'],'guard_v1_interpretation':'One pulse per case but width dependence collapses to about0.003us across0.3V. Strict monotonicity alone is inadequate. Not accepted weighted contribution.','guard_v2_cases':g2['cases'],'guard_v2_width_span_us':g2['width_span_us'],'signed_charge_cases':signed['cases'],'signed_response_observed':signed['signed_response_observed'],'larger_positive_weight_delivers_more_charge':signed['larger_positive_weight_delivers_more_charge'],'limits':'Nominal three-case characterization only. All phase/bias/programming commands external. No calibrated original-float transfer, mismatch/noise acceptance, autonomous sequencing or dense/full-chip area claim. Signed parent v1 physical views preserved without simulation. Native Netgen deep-name flattening overflow retained; v2 flat LVS uses frozen already matched reference netlist.','full_chip_layout_complete':False,'original_float_accuracy_accepted':False,'full_5ms_population_service_accepted':False,'sha256':{rel(p):sha(p) for p in sorted(paths)}}
 ap=BASE/'results/gf180_signed_weight_charge_boundary.json';assert not ap.exists();ap.write_text(json.dumps(audit,indent=2)+'\n')
 docs=[ROOT/'docs'/n for n in ['AGENTS.md','ACTIVE_TASKS.md','ARCHITECTURE.md','DECISIONS.md','RESULTS.md','PROGRESS.md','project_spec.yaml']];stamp=datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%SZ');zp=BASE/'documentation_history'/('project_docs_before_signed_weight_charge_'+stamp+'.zip')
 with zipfile.ZipFile(zp,'x',zipfile.ZIP_DEFLATED) as z:
  for p in docs:z.writestr(rel(p),p.read_bytes())
 zp.with_suffix('.json').write_text(json.dumps({'archive_sha256':sha(zp),'files':{rel(p):{'bytes':p.stat().st_size,'sha256':sha(p)} for p in docs}},indent=2)+'\n')
 widths='/'.join(f"{c['pulse_width_us']:.3f}" for c in g2['cases']);steps='/'.join(f"{c['state_step_v']*1000:+.3f}" for c in signed['cases']);signedok=signed['signed_response_observed'];weightok=signed['larger_positive_weight_delivers_more_charge']
 section=f'''\n## Physically joined weighted signed-charge path - 2026-10-10\n\n[Boundary audit](../{rel(ap)}) and [catalog revision6](../{rel(cp)}): nine reusable module artifact sets and six characterization assemblies have physical views and completed nominal simulations. This is module-level evidence; full layout remains unfinished.\n\nGuarded duration parent revision1 passes layout checks and produces one pulse but weights collapse to0.938–0.941us. Revision2 removes added debug-node routing, shortens global nets and places the cutoff inverter beside the duration parent. Actual44MOS/4MIM parent extraction has250 nonnegative branches; three programmed magnitudes1.5/1.65/1.8V give{widths}us with one pulse each. This is a combined routing change, not an isolated causal attribution.\n\nRouted signed-charge parent revision2 contains70MOS/4MIM, native sign inverter/two AND gates and bipolar injector. DRC/LVS/GDS readback/LEF pass; flat view has542 nonnegative branches. Netgen crashed while expanding the deep original hierarchy; flat LVS against the frozen reference already uniquely matched to that hierarchy passes. Failed output preserved. Initial combined three-case simulation timed out near cutoff; three sequential bounded cases retain the same circuit, biases and tolerances. Three native cases small-positive/large-positive/large-negative produce state steps{steps}mV on two minimum MIM loads. Correct signed response:{signedok}; larger positive weight delivers more net charge:{weightok}. Net charge includes switching transients and uses fixed source biases2.5/.45V.\n\nExternal references, programming and phases remain. No calibrated float weight map, original-model accuracy, full-population5ms service, dense layout or full-chip acceptance is claimed. Preserve transfer errors and proceed to remaining support functions, dense tiles and full hierarchy; refine precision later.\n'''
 p=ROOT/'docs/RESULTS.md';s=p.read_text();i=s.index('\n## ');s=s[:i]+section+s[i:];s=s.replace('Guard-to-parent wiring is still schematic; physically integrating it is next.','That earlier fixture used schematic guard wiring; the later physically joined result is recorded above.');p.write_text(s)
 p=ROOT/'docs/ACTIVE_TASKS.md';s=p.read_text().replace('Three routed characterization assemblies also pass layout checks and have completed simulations. Pulse-termination guard corrects cutoff chatter in an extracted fixture; physically joining it remains next.','Six routed characterization assemblies now have physical checks and completed nominal simulations, including guarded duration and its signed-charge connection.').replace('three characterization assemblies','six characterization assemblies').replace('article_module_catalog_v5.json','article_module_catalog_v6.json').replace('catalog revision5','catalog revision6');a=s.index('| Job status |');b=s.index('\n',a);s=s[:a]+'| Job status | Guarded duration and signed-charge parent revision2 nominal simulations completed; no live simulator |'+s[b:];a=s.index('2. Native ramp-duration');b=s.index('\n3. Complete',a);s=s[:a]+f'2. Physically joined duration guard revision2 gives{widths}us at three magnitudes. Signed-charge parent revision2 completed: state steps{steps}mV; correct signs={signedok}, larger positive charge={weightok}. Preserve routing-revision failures and nominal imperfections; continue remaining support functions.'+s[b:];s=s.replace('native termination guard gives one clean pulse at three programmed magnitudes in extracted fixture','routed guarded duration and signed-charge path have completed nominal extracted simulations');p.write_text(s)
 p=ROOT/'docs/PROGRESS.md';s=p.read_text();i=s.index('\n## Milestones');s=s[:i]+f'\nWeighted signed-charge integration milestone: guarded duration revision2 restores{widths}us after revision1 routing collapsed magnitude dependence. Signed-charge parent revision2 completes physical views and three native nominal cases ({steps}mV). Catalog revision6 records nine modules/six characterization assemblies. Full hierarchy remains unfinished. Exact pre-update docs: `{rel(zp)}`.\n'+s[i:];p.write_text(s)
 p=ROOT/'docs/ARCHITECTURE.md';s=p.read_text().replace('A native dynamic pulse-termination guard fixture gives one pulse; physical guard integration remains next.','The physically joined guard revision2 produces one pulse with preserved magnitude dependence. A70MOS/4MIM parent joins it to real sign selection and bipolar injection: SIGN0 selects positive and SIGN1 negative; sign must remain stable during ARM. External phase/bias/programming commands remain.');p.write_text(s)
 p=ROOT/'docs/DECISIONS.md';s=p.read_text();i=s.find('\n## ');s=s[:i]+'\n## Retain physically guarded pulse duration - 2026-10-10\n\nRouting revision2 restores weight-dependent pulse duration after revision1 collapsed it. Continue this native analog path and its real signed-gate/injector connection. Require pulse-count and delivered-charge/range evidence; strict monotonicity alone can label an almost constant pulse as passing. No switched-capacitor fallback or digital membrane change is needed at this nominal mechanism gate. Accuracy and full-population throughput remain unaccepted.\n'+s[i:];p.write_text(s)
 p=ROOT/'docs/project_spec.yaml';raw=p.read_bytes();h,t=raw.split(b'\ndocument:',1);s=h.decode().replace('article_module_catalog_v5.json','article_module_catalog_v6.json').replace('gf180_analog_weight_control_boundary.json','gf180_signed_weight_charge_boundary.json').replace('  live_sessions: [signed_weight_charge_parent_v2_singlecase2_bounded_120s]','  live_sessions: []').replace('status: guarded_duration_routing_revision2_complete_signed_charge_simulation_running','status: nine_modules_six_assemblies_guarded_duration_signed_charge_nominal_complete').replace('next_action: physically_join_termination_guard_then_signed_injection_remaining_functions_dense_tile_full_assembly','next_action: remaining_bias_phase_adaptation_inhibition_readout_functions_dense_tile_full_assembly');p.write_bytes(s.encode()+b'\ndocument:'+t)
 print(json.dumps({'catalog':rel(cp),'audit':rel(ap),'widths_us':widths,'state_steps_mv':steps,'signed':signedok,'larger_positive_charge':weightok},indent=2))
if __name__=='__main__':main()
